"""The one-learner gymnasium adapter over a `core.Env`, and the library model as an Agent (AD-03)."""

from collections.abc import Callable
from pathlib import Path
from typing import Any

import gymnasium as gym
import numpy as np
from stable_baselines3 import DQN

from rllab.core import SOLO, Env, Transition

TRAIN_SEEDS = 1_000_000
"""Game seeds drawn for training stay below this; evaluation seeds start at it."""


class SoloGymEnv(gym.Env[np.ndarray, np.int64]):
    """The single team of a `core.Env` as a `gymnasium.Env` with one discrete-action agent."""

    def __init__(self, env: Env) -> None:
        spec = env.teams[SOLO]
        self.env = env
        self.observation_space = gym.spaces.Box(-np.inf, np.inf, spec.obs_shape, np.float32)
        self.action_space = gym.spaces.Discrete(spec.actions.n)

    def reset(
        self, *, seed: int | None = None, options: dict[str, Any] | None = None
    ) -> tuple[np.ndarray, dict[str, Any]]:
        """Start a game on a training seed drawn from the adapter's seeded generator."""
        super().reset(seed=seed)
        obs, info = self.env.reset(int(self.np_random.integers(TRAIN_SEEDS)))
        return obs[SOLO][0], dict(info)

    def step(self, action: np.int64) -> tuple[np.ndarray, float, bool, bool, dict[str, Any]]:
        """One step of the one agent; termination and truncation stay apart."""
        result = self.env.step({SOLO: np.array([action], dtype=np.int64)})
        reward = float(result.reward[SOLO][0])
        return result.obs[SOLO][0], reward, result.terminated, result.truncated, dict(result.info)


class ModelAgent:
    """The model being trained, played greedily as a one-agent `core.Agent`."""

    def __init__(self, model: DQN) -> None:
        self.model = model

    def act(self, obs: np.ndarray, *, explore: bool) -> np.ndarray:
        """The model's action for each agent of the batch; `explore` uses its exploration rate."""
        actions, _ = self.model.predict(obs, deterministic=not explore)
        return np.asarray(actions, dtype=np.int64).reshape(len(obs))

    def learn(self, t: Transition) -> None:
        """The library model learns only inside its own `learn` loop."""
        raise RuntimeError("the reference model learns through Stable-Baselines3, not learn()")

    def save(self, path: Path) -> None:
        """Save the model's zip at `path`."""
        self.model.save(path)

    def load(self, path: Path) -> None:
        """Replace the model by the one saved at `path`."""
        self.model = DQN.load(path, device="cpu")


def make_gym_env(make_env: Callable[[], Env]) -> SoloGymEnv:
    """The adapter over a fresh environment."""
    return SoloGymEnv(make_env())

